                insert candidate;
                u = candidate;
            } catch (DmlException e) {
                u = null;
            }
        }
        if (u == null) {
            List<User> existing = [
                SELECT Id FROM User
                WHERE IsActive = true
                AND UserType = 'Standard'
                AND ProfileId = :UserInfo.getProfileId()
                AND Id != :UserInfo.getUserId()
                LIMIT 1
            ];
            if (!existing.isEmpty()) {
                u = existing[0];
            } else {
                u = new User(Id = UserInfo.getUserId());
            }
