    private static Account newAccount(String name, String rating) {
        return new Account(Name = name, Rating = rating);
    }

    private static Opportunity newOpp(String name, String stage, Id accountId) {
        return new Opportunity(
            Name = name,
            StageName = stage,
            CloseDate = CLOSE,
            AccountId = accountId
        );
    }

    private static List<Task> tasksFor(Set<Id> oppIds) {
        return [
            SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
            FROM Task
            WHERE WhatId IN :oppIds
        ];
    }

    private static List<Task> tasksFor(Id oppId) {
        return tasksFor(new Set<Id>{ oppId });
    }

    private static Opportunity reload(Id oppId) {
        return [SELECT Id, NextStep, StageName, OwnerId, CloseDate FROM Opportunity WHERE Id = :oppId];
    }

