/**
 * Pure unit tests for RenewalService.createRenewals.
 * No DML, no SOQL: the selector and the unit of work are mocked with ApexMocks and
 * injected through the Application factories. All ids are fake (fflib_IDGenerator).
 * Because the renewals and tasks never receive ids, the assertions inspect the
 * arguments that the service passes to the mocked unit of work.
 */
@IsTest
private class RenewalServiceTest {

    private static final String CLOSED_WON = 'Closed Won';

    /** Holds the mocks for one test. */
    private class Fixture {
        public fflib_ApexMocks mocks;
        public IOpportunitiesSelector selectorMock;
        public fflib_ISObjectUnitOfWork uowMock;
    }

    /** One captured call to registerNew(SObject, SObjectField, SObject). */
    private class TaskRegistration {
        public Task reminder;
        public SObject relatedTo;
    }

    // ------------------------------------------------------------------------------------
    // Tests
    // ------------------------------------------------------------------------------------

    @IsTest
    static void closedWonOpportunity_registersRenewalAndReminderAndCommits() {
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id ownerId = fflib_IDGenerator.generate(User.SObjectType);
        Opportunity won = buildOpportunity(
            'Acme Deal', accountId, ownerId, CLOSED_WON, Date.newInstance(2024, 3, 15), 999.99
        );
        Set<Id> ids = new Set<Id>{ won.Id };
        Fixture f = setUp(ids, new List<Opportunity>{ won });

        RenewalService.createRenewals(ids);

        // purity check
        Assert.areEqual(0, Limits.getDmlStatements(), 'Unit test must not perform DML');
        Assert.areEqual(0, Limits.getQueries(), 'Unit test must not perform SOQL');

        // selector used with the given ids
        ((IOpportunitiesSelector) f.mocks.verify(f.selectorMock, 1)).selectById(ids);

        // renewal opportunity
        List<Opportunity> renewals = captureRenewals(f, 1);
        Opportunity renewal = renewals[0];
        Assert.isNull(renewal.Id, 'Renewal must be a new record');
        Assert.areEqual('Acme Deal - Renewal', renewal.Name, 'Renewal name');
        Assert.areEqual(accountId, renewal.AccountId, 'Renewal must keep the original account');
        Assert.areEqual('Prospecting', renewal.StageName, 'Renewal stage');
        Assert.areEqual(Date.newInstance(2025, 3, 15), renewal.CloseDate, 'Renewal close date = original + 1 year');
        assertRenewalAmount(won.Amount, renewal.Amount, 'Acme Deal - Renewal');

        // reminder task
        List<TaskRegistration> tasks = captureTasks(f, 1);
        Task reminder = tasks[0].reminder;
        Assert.areEqual('Prepare renewal for Acme Deal', reminder.Subject, 'Task subject');
        Assert.areEqual(ownerId, reminder.OwnerId, 'Task owner = original opportunity owner');
        Assert.areEqual(Date.newInstance(2025, 1, 14), reminder.ActivityDate, 'Task date = renewal close date - 60 days');
        Assert.areEqual(renewal.CloseDate.addDays(-60), reminder.ActivityDate, 'Task date relative to renewal close date');

        // task is related to the new renewal, not to the original opportunity
        SObject relatedTo = tasks[0].relatedTo;
        Assert.isNotNull(relatedTo, 'Task must be related to a record');
        Assert.isTrue(relatedTo instanceof Opportunity, 'Task must be related to an opportunity');
        Assert.isNull(relatedTo.Id, 'Task must be related to the new renewal, not the original opportunity');
        Assert.isTrue(relatedTo === renewal, 'Task must be related to the registered renewal instance');

        // commit exactly once
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, 1)).commitWork();
    }

    @IsTest
    static void mixedOpportunities_onlyClosedWonWithCloseDateAreRenewed() {
        Id accountA = fflib_IDGenerator.generate(Account.SObjectType);
