        Opportunity lost = buildOpportunity('Lost Deal', accountB, ownerB, 'Closed Lost', Date.newInstance(2024, 1, 1), 700);
        Opportunity wonNoDate = buildOpportunity('No Date Deal', accountA, ownerB, CLOSED_WON, null, 900);

        List<Opportunity> selected = new List<Opportunity>{ open, wonA, lost, wonNoDate, wonB };
        Set<Id> ids = new Set<Id>();
