            Assert.areEqual(original.OwnerId, reg.reminder.OwnerId, 'Task owner = original owner');
            Assert.areEqual(relatedRenewal.CloseDate.addDays(-60), reg.reminder.ActivityDate, 'Task activity date');
            renewalsWithTask.add(relatedRenewal.Name);
        }
        Assert.areEqual(originalByRenewalName.keySet(), renewalsWithTask, 'Each renewal gets exactly one reminder');

        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, 1)).commitWork();
    }

    @IsTest
    static void closedWonWithoutAmount_renewalHasNoAmount() {
